const DropNode = ({ id, data }) => {
  const label = data.label || "";
  const ph = data.ph || "";
  const form = data.form || "";
  const isDisabled = data.isDisabled;

  console.log("label ==>", label, "isDisabled ==>", isDisabled);

  const [{ isOver }, drop] = useDrop(
    () => ({
      accept: "word",
      canDrop: () => !isDisabled, // Prevent drop for disabled nodes
      drop: (item) => {
        if (!isDisabled && data.onDrop) {
          data.onDrop(id, item.word);
        }
      },
      collect: (monitor) => ({
        isOver: !!monitor.isOver(),
      }),
    }),
    [isDisabled]
  );

  const handleClick = () => {
    if (isDisabled) {
      // Handle click for disabled nodes, even though they can't accept drops
      Swal.fire({
        title: "Info",
        html: `
         It is the ${ph}.
         `,
        icon: "info",
        confirmButtonColor: "#0F477E"
      });
    } else if (!label) {
      Swal.fire({text:"No word dropped here yet.",confirmButtonColor: "#0F477E"});
    } else if (data.status === "correct") {
      Swal.fire({
        title: "Correct",
        text: `"${label}" is correct. It is the ${ph}.`,
        icon: "success",
        confirmButtonColor: "#0F477E"
      });
    } else {
      Swal.fire({
        title: "Incorrect",
        html: `
        "${label}" is incorrect. ${ph} is expected at this place.<br></br>
         <b>Hint</b>: ${form}
         `,
        icon: "error",
        confirmButtonColor: "#0F477E"
      });
    }
  };

  // Node color feedback
  let bgColor = "#fff";
  if (isDisabled) bgColor = "#d4edda"; // Light green for pre-filled correct
  else if (isOver) bgColor = "#dff0d8";
  else if (data.status === "correct") bgColor = "#d4edda";
  else if (data.status === "wrong") bgColor = "#f8d7da";

  return (
    <div
      ref={isDisabled ? null : drop}
      onClick={handleClick} // Allow clicking even if disabled
      style={{
        width: 100,
        height: 100,
        borderRadius: "50%",
        border: "2px solid black",
        textAlign: "center",
        padding: "5px",
        fontWeight: "bold",
        backgroundColor: bgColor,
        position: "relative",
        color: "grey",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        lineHeight: "1.2",
        wordWrap: "break-word",
        fontSize: "calc(.6rem + .3vw)",
        pointerEvents: isDisabled ? "auto" : "auto", // Allow interaction even if the drop is disabled
        cursor: "pointer"
      }}
    >
      {label || ph}
      <Handle type="target" position={Position.Top} />
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
};

export default DropNode