import React, { useRef, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import Button from "@mui/material/Button";
import video from "../Images/intro_video.mp4"; // replace with actual path
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";

function Selectlevel() {
  const navigate = useNavigate();
  const { t } = useTranslation();

  const [flag, setFlag] = useState(true);
  const videoRef = useRef(null);

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("Activity start page");


  const skipbtn = () => {
    navigate("/launchpage/englishactivity/level");
    setFlag(true);

     ReactGA.event({
      action:
        'English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on "Skip" button of video',
      category: 'English CDAC-OlabsNxtG-En-34 | "Skip" button of video clicked',
      label:
        'English CDAC-OlabsNxtG-En-34 | "Skip" button of video clicked and to skip the video',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Skip" button of video',
      "Clicked",
      '"Skip" button of video clicked to skip the video'
    );
   }

  const handleletsgobtn = () => {
    // Pause and clean up the video before navigating
    if (videoRef.current) {
      videoRef.current.pause();
      videoRef.current.currentTime = 0;
    }
    ReactGA.event({
      action:
        "English Verb word | CDAC-OlabsNxtG-En-38 | Clicked on \"Let's Go\" button",
      category:
        "English CDAC-OlabsNxtG-En-38 | \"Let's Go\" button clicked",
      label:
        "English CDAC-OlabsNxtG-En-38 | \"Let's Go\" button clicked to start the activity.",
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      "\"Let's Go\" button",
      "Clicked",
      "\"Let's Go\" button to start the activity."
    );

    navigate("/launchpage/englishactivity/level");
  };

  const end = () => {
    setFlag(false);
  };

  return (
    <div
      className="scrollbar-primary row d-flex p-3"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        className="row d-flex justify-content-center align-items-center"
        style={{ height: "90%" }}
      >
        {flag ? (
          <video
            className="video"
            ref={videoRef}
            width="50%"
            height="65%"
            autoPlay
            muted
            onEnded={end}
          >
            <source src={video} type="video/mp4" />
          </video>
        ) : (
          <div className="d-flex justify-content-center">
            <h6
              style={{
                background: "#EDF6FA",
                boxShadow: "rgba(0, 0, 0, 0.25) 0px 54px 55px, rgba(0, 0, 0, 0.12) 0px -12px 30px, rgba(0, 0, 0, 0.12) 0px 4px 6px, rgba(0, 0, 0, 0.17) 0px 12px 13px, rgba(0, 0, 0, 0.09) 0px -3px 5px",
                padding: "2vh",
                borderRadius: "1vh",
                fontSize: "calc(.6rem + .4vw)",
                cursor:"pointer"
              }}
            >
              Click on "LET'S GO" button to start the activity.
            </h6>
          </div>
        )}
      </div>

      <div
        className="row-md-auto d-flex justify-content-center align-items-center justify-content-around"
        style={{ paddingTop: "5px", height: "10%" }}
      >
        <Button id="letgo" variant="contained" onClick={skipbtn} sx={{ fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E" }} disabled={flag == false}>
          {t("skip")}
        </Button>
        <Button id="letgo" variant="contained" onClick={handleletsgobtn} sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }} disabled={flag}>
          {t("lets_go")}
        </Button>
      </div>
    </div>
  );
}

export default Selectlevel;
